/*
  ESP32-S2 Roblox keyboard bot
  - USB HID keyboard
  - Presses W to move forward
  - Jumps with Space at intervals
  - Start/stop with the BOOT button
  Tested concept for Arduino-ESP32 USB-capable ESP32-S2 boards.

  Arduino IDE settings:
  Board: ESP32S2 Dev Module
  USB CDC On Boot: Enabled
  USB Mode: USB-OTG (TinyUSB)
*/

#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

#ifndef BOOT_PIN
#define BOOT_PIN 0
#endif

bool running = false;
bool lastButton = HIGH;
unsigned long lastJump = 0;
unsigned long lastStatus = 0;

const unsigned long jumpInterval = 2500;
const unsigned long moveBurst = 700;

void setup() {
  pinMode(BOOT_PIN, INPUT_PULLUP);

  USB.begin();
  Keyboard.begin();

  delay(1500); // allow USB enumeration
}

void loop() {
  bool button = digitalRead(BOOT_PIN);

  if (lastButton == HIGH && button == LOW) {
    running = !running;
    delay(250);
  }
  lastButton = button;

  if (!running) {
    Keyboard.releaseAll();
    delay(20);
    return;
  }

  // Walk forward briefly.
  Keyboard.press('w');
  delay(moveBurst);
  Keyboard.release('w');

  // Jump periodically.
  if (millis() - lastJump >= jumpInterval) {
    Keyboard.press(KEY_SPACE);
    delay(100);
    Keyboard.release(KEY_SPACE);
    lastJump = millis();
  }

  delay(80);
}
